export function quote(products, tenant, items) {
  if (!Array.isArray(items) || !items.length) throw new TypeError('items');
  const seen = new Set();
  const lines = items.map(({ productId, quantity }) => {
    if (seen.has(productId)) throw new TypeError('duplicate product');
    seen.add(productId);
    const product = products.find(p => p.id === productId && p.tenant === tenant);
    if (!product) throw new Error('product');
    if (!Number.isSafeInteger(quantity) || quantity <= 0) throw new RangeError('quantity');
    const lineCents = product.priceCents * quantity;
    if (!Number.isSafeInteger(lineCents)) throw new RangeError('total');
    return { productId, quantity, unitCents: product.priceCents, lineCents };
  });
  const subtotalCents = lines.reduce((sum, line) => sum + line.lineCents, 0);
  if (!Number.isSafeInteger(subtotalCents)) throw new RangeError('total');
  return { lines, subtotalCents, discountCents: 0, totalCents: subtotalCents };
}

