import { quote } from './pricing.mjs';
export function createShop({ products = [] } = {}) {
  const catalog = structuredClone(products);
  return {
    quote(tenant, items) { return quote(catalog, tenant, items); },
    inventory(tenant) { return catalog.filter(p => p.tenant === tenant).map(p => ({ ...p, available: p.stock })); },
  };
}

