import test from 'node:test';
import assert from 'node:assert/strict';
import { createShop } from '../src/index.mjs';
test('existing quote and detached inventory', () => {
  const shop = createShop({ products: [{ id: 'p', tenant: 'a', priceCents: 250, stock: 4 }] });
  assert.equal(shop.quote('a', [{ productId: 'p', quantity: 2 }]).totalCents, 500);
  const copy = shop.inventory('a'); copy[0].stock = 0;
  assert.equal(shop.inventory('a')[0].stock, 4);
});
